//! M8-11b contract tests of the sound decoder (spec criteria 1 and 2,
//! D2904): OGG Vorbis and MP3 into a `Clip`, WAV unchanged, and every way a
//! file can be wrong ends in an `Err`, never in a panic.
//!
//! The fixtures in `tests/fixtures/` were generated by us with ffmpeg
//! (`sine`/`anullsrc` sources, libvorbis and libmp3lame): no third-party
//! material, no license. The files of the Lichess packs are used only to
//! prove that the decoder reads the packs we embed.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::path::{Path, PathBuf};

use mychess_app::sound::{Clip, PANIC_MESSAGE, SoundFileError, decode_clip, decode_file};

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name)
}

fn bytes(name: &str) -> Vec<u8> {
    std::fs::read(fixture(name)).expect("fixture")
}

fn seconds(clip: &Clip) -> f64 {
    let frames = clip.samples.len() / usize::from(clip.channels);
    f64::from(u32::try_from(frames).unwrap()) / f64::from(clip.sample_rate)
}

/// A 16-bit mono PCM WAV, built by hand.
fn wav(rate: u32, samples: &[i16]) -> Vec<u8> {
    let data: Vec<u8> = samples.iter().flat_map(|s| s.to_le_bytes()).collect();
    wav_with_data_size(rate, &data, u32::try_from(data.len()).unwrap())
}

fn wav_with_data_size(rate: u32, data: &[u8], declared: u32) -> Vec<u8> {
    let mut out = b"RIFF".to_vec();
    out.extend_from_slice(&(36 + declared).to_le_bytes());
    out.extend_from_slice(b"WAVEfmt ");
    out.extend_from_slice(&16_u32.to_le_bytes());
    out.extend_from_slice(&1_u16.to_le_bytes());
    out.extend_from_slice(&1_u16.to_le_bytes());
    out.extend_from_slice(&rate.to_le_bytes());
    out.extend_from_slice(&(rate * 2).to_le_bytes());
    out.extend_from_slice(&2_u16.to_le_bytes());
    out.extend_from_slice(&16_u16.to_le_bytes());
    out.extend_from_slice(b"data");
    out.extend_from_slice(&declared.to_le_bytes());
    out.extend_from_slice(data);
    out
}

#[test]
fn reads_a_small_mono_ogg_vorbis() {
    let clip = decode_clip(&bytes("tone_mono_44100.ogg")).unwrap();
    assert_eq!((clip.sample_rate, clip.channels), (44_100, 1));
    let s = seconds(&clip);
    assert!((0.18..=0.22).contains(&s), "{s} s");
    let peak = clip.samples.iter().fold(0.0_f32, |m, v| m.max(v.abs()));
    assert!(peak > 0.1 && peak <= 1.0, "peak {peak}");
}

#[test]
fn reads_a_small_stereo_ogg_vorbis_at_another_rate() {
    let clip = decode_clip(&bytes("tone_stereo_22050.ogg")).unwrap();
    assert_eq!((clip.sample_rate, clip.channels), (22_050, 2));
    assert_eq!(clip.samples.len() % 2, 0);
    assert!((0.18..=0.22).contains(&seconds(&clip)));
}

#[test]
fn reads_mp3_with_and_without_tags() {
    let tagged = decode_clip(&bytes("tone_mono_44100.mp3")).unwrap();
    assert_eq!((tagged.sample_rate, tagged.channels), (44_100, 1));
    // The encoder delay is left in (D2904): a little longer than the tone.
    let s = seconds(&tagged);
    assert!((0.18..=0.30).contains(&s), "{s} s");
    let plain = decode_clip(&bytes("tone_stereo_44100_noid3.mp3")).unwrap();
    assert_eq!((plain.sample_rate, plain.channels), (44_100, 2));
    assert!(plain.samples.iter().any(|v| v.abs() > 0.05));
}

#[test]
fn wav_is_read_by_the_own_reader_unchanged() {
    let clip = decode_clip(&wav(8_000, &[0, 16_384, -16_384, 32_767])).unwrap();
    assert_eq!((clip.sample_rate, clip.channels), (8_000, 1));
    assert_eq!(clip.samples.len(), 4);
    assert!((clip.samples[1] - 0.5).abs() < 1e-4);
    assert!((clip.samples[2] + 0.5).abs() < 1e-4);
}

#[test]
fn decode_file_reads_from_disk_and_the_content_chooses_the_format() {
    let dir = tempfile::tempdir().unwrap();
    // A Vorbis file named like a WAV is still read as Vorbis.
    let swapped = dir.path().join("move.wav");
    std::fs::write(&swapped, bytes("tone_mono_44100.ogg")).unwrap();
    let clip = decode_file(&swapped).unwrap();
    assert_eq!(clip.sample_rate, 44_100);
    // And an MP3 named .ogg.
    let swapped = dir.path().join("move.ogg");
    std::fs::write(&swapped, bytes("tone_mono_44100.mp3")).unwrap();
    assert_eq!(decode_file(&swapped).unwrap().channels, 1);
}

#[test]
fn a_file_with_the_wrong_content_for_its_extension_is_an_error() {
    let dir = tempfile::tempdir().unwrap();
    for name in ["move.ogg", "move.mp3", "move.wav"] {
        let path = dir.path().join(name);
        std::fs::write(&path, b"This is plain text, not a sound at all.").unwrap();
        assert!(decode_file(&path).is_err(), "{name}");
    }
}

#[test]
fn empty_and_header_only_files_are_errors() {
    assert_eq!(decode_clip(&[]), Err(SoundFileError::Empty));
    let ogg = bytes("tone_mono_44100.ogg");
    // Only the first page header, and only the first page.
    assert!(decode_clip(&ogg[..27]).is_err());
    assert!(decode_clip(&ogg[..58]).is_err());
    assert!(decode_clip(b"ID3\x04\0\0\0\0\0\0").is_err());
    assert!(decode_clip(&[0xFF, 0xFB, 0x90, 0x00]).is_err());
    // A WAV header whose data chunk is empty.
    assert!(decode_clip(&wav(8_000, &[])).is_err());
}

#[test]
fn every_truncation_of_an_ogg_is_an_error_and_never_a_panic() {
    let ogg = bytes("tone_mono_44100.ogg");
    for len in 0..ogg.len() {
        assert!(decode_clip(&ogg[..len]).is_err(), "cut at {len}");
    }
    assert!(decode_clip(&ogg).is_ok());
}

/// Fails when the result is the error that stands for a caught panic.
fn assert_no_panic(result: &Result<Clip, SoundFileError>, what: &str) {
    if let Err(SoundFileError::Decoder(message)) = result {
        assert!(
            !message.contains("panicked") && message != PANIC_MESSAGE,
            "{what}: the decoder panicked"
        );
    }
}

#[test]
fn truncated_mp3_never_panics_and_a_cut_header_is_an_error() {
    let mp3 = bytes("tone_mono_44100.mp3");
    for len in 0..mp3.len() {
        let result = decode_clip(&mp3[..len]);
        assert_no_panic(&result, &format!("mp3 cut at {len}"));
        if len < 4 {
            assert!(result.is_err(), "cut at {len}");
        }
    }
}

#[test]
fn flipping_any_byte_never_panics() {
    for name in ["tone_mono_44100.ogg", "tone_mono_44100.mp3"] {
        let original = bytes(name);
        for at in 0..original.len() {
            let mut damaged = original.clone();
            damaged[at] ^= 0xFF;
            assert_no_panic(&decode_clip(&damaged), &format!("{name} byte {at}"));
        }
    }
}

#[test]
fn a_wav_promising_billions_of_samples_is_refused_without_allocating() {
    // The header says 4 GiB of data; the file has 6 bytes.
    let bomb = wav_with_data_size(44_100, &[1, 2, 3, 4, 5, 6], u32::MAX - 100);
    assert_eq!(decode_clip(&bomb), Err(SoundFileError::Truncated));
}

#[test]
fn a_wav_longer_than_thirty_seconds_is_refused() {
    let samples = vec![0_i16; 8_000 * 31];
    assert_eq!(
        decode_clip(&wav(8_000, &samples)),
        Err(SoundFileError::TooLong)
    );
}

#[test]
fn ogg_and_mp3_longer_than_thirty_seconds_are_refused() {
    // 31 s of silence: a few KB on disk, 248 000 samples when decoded.
    assert_eq!(
        decode_clip(&bytes("silence_31s.ogg")),
        Err(SoundFileError::TooLong)
    );
    assert_eq!(
        decode_clip(&bytes("silence_31s.mp3")),
        Err(SoundFileError::TooLong)
    );
}

#[test]
fn rate_and_channels_outside_the_limits_are_refused() {
    assert_eq!(
        decode_clip(&bytes("rate_4000.ogg")),
        Err(SoundFileError::BadRate(4_000))
    );
    assert_eq!(
        decode_clip(&bytes("six_channels.ogg")),
        Err(SoundFileError::BadChannels(6))
    );
    assert_eq!(
        decode_clip(&wav(4_000, &[1, 2, 3])),
        Err(SoundFileError::BadRate(4_000))
    );
}

#[test]
fn a_file_over_eight_mebibytes_is_too_large() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("huge.ogg");
    let mut data = b"OggS".to_vec();
    data.resize(8 * 1024 * 1024 + 1, 0);
    std::fs::write(&path, &data).unwrap();
    assert_eq!(decode_file(&path), Err(SoundFileError::TooLarge));
    assert_eq!(decode_clip(&data), Err(SoundFileError::TooLarge));
}

#[test]
fn a_missing_file_is_an_io_error() {
    let dir = tempfile::tempdir().unwrap();
    assert!(matches!(
        decode_file(&dir.path().join("none.ogg")),
        Err(SoundFileError::Io(_))
    ));
}

/// The rows of a `CREDITS.md` table: (file, rate, channels, seconds).
fn credits_rows(text: &str) -> Vec<(String, u32, u16, f64)> {
    text.lines()
        .filter(|l| l.starts_with("| `") && l.contains("Ogg Vorbis"))
        .map(|line| {
            let cells: Vec<&str> = line.split('|').map(str::trim).collect();
            let file = cells[1].trim_matches('`').to_owned();
            let format = cells[4];
            let parts: Vec<&str> = format.split(", ").collect();
            let rate = parts[1].trim_end_matches(" Hz").parse().unwrap();
            let channels = parts[2].trim_end_matches(" canais").parse().unwrap();
            let secs = parts[3].trim_end_matches(" s").parse().unwrap();
            (file, rate, channels, secs)
        })
        .collect()
}

#[test]
fn the_decoder_reads_every_bundled_pack_file_as_credits_describes() {
    let sounds = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../assets/sounds");
    for pack in ["sfx", "nes", "futuristic", "piano"] {
        let credits = std::fs::read_to_string(sounds.join(pack).join("CREDITS.md")).unwrap();
        let rows = credits_rows(&credits);
        assert_eq!(rows.len(), 8, "{pack}");
        for (file, rate, channels, secs) in rows {
            let clip = decode_file(&sounds.join(pack).join(&file))
                .unwrap_or_else(|e| panic!("{pack}/{file}: {e}"));
            assert_eq!(clip.sample_rate, rate, "{pack}/{file}");
            assert_eq!(clip.channels, channels, "{pack}/{file}");
            assert!(
                (seconds(&clip) - secs).abs() <= 0.02,
                "{pack}/{file}: {} s, credits say {secs} s",
                seconds(&clip)
            );
        }
    }
}
